def play_rack_endgame(points):
    size = len(points)
    if size == 0:
        return ["none", 0]
    if size == 1:
        return ["left", points[0]]
    margins = []
    for left in range(size):
        row = []
        for right in range(size):
            row.append(0)
        row[left] = points[left]
        margins.append(row)
    for width in range(2, size):
        for left in range(size - width + 1):
            right = left + width - 1
            from_left = points[left] - margins[left + 1][right]
            from_right = points[right] - margins[left][right - 1]
            if from_left >= from_right:
                margins[left][right] = from_left
            else:
                margins[left][right] = from_right
    from_left = points[0] - margins[1][size - 1]
    from_right = points[size - 1] - margins[0][size - 2]
    if from_left >= from_right:
        return ["left", from_left]
    return ["right", from_right]
